source /tmp/probe-implicit/r.sh
gen(){ w="$1"; n=${#w}; for ((m=0; m<(1<<n); m++)); do s=""; for ((i=0;i<n;i++)); do c="${w:i:1}"; if (( (m>>i)&1 )); then c=$(printf '%s' "$c" | tr 'a-z' 'A-Z'); fi; s="$s$c"; done; /workspace/dataset/test13_executable --a "$s" 2>/dev/null | head -1 | grep -q '!!bool' && printf '%s=BOOL ' "$s" || printf '%s=str ' "$s"; done; echo; }
for w in yes no on off; do echo "-- $w"; gen "$w"; done

source /tmp/probe-implicit/r.sh
gen2(){ w="$1"; n=${#w}; for ((m=0; m<(1<<n); m++)); do s=""; for ((i=0;i<n;i++)); do c="${w:i:1}"; if (( (m>>i)&1 )); then c=$(printf '%s' "$c" | tr 'a-z' 'A-Z'); fi; s="$s$c"; done; t=$(/workspace/dataset/test13_executable --a "$s" 2>/dev/null | head -1); case "$t" in '!!bool'*|'!!null'*|'!!float'*) printf '%s=%s ' "$s" "${t%% *}";; esac; done; echo; }
for w in true false null nan inf; do echo "-- $w"; gen2 "$w"; done
echo "-- .nan/.inf casings"
gen3(){ w="$1"; n=${#w}; for ((m=0;m<(1<<n);m++)); do s=""; for ((i=0;i<n;i++)); do c="${w:i:1}"; if (( (m>>i)&1 )); then c=$(printf '%s' "$c"|tr 'a-z' 'A-Z'); fi; s="$s$c"; done; t=$(/workspace/dataset/test13_executable --a ".$s" 2>/dev/null|head -1); case "$t" in '!!float'*) printf '.%s=%s ' "$s" "$t";; esac; done; echo; }
gen3 nan; gen3 inf

